def mean(values):
    return sum(values) / len(values)


def median(values):
    ordered = sorted(values)
    middle = len(ordered) // 2
    return ordered[middle]


def variance(values):
    average = mean(values)
    return sum((value - average) ** 2 for value in values) / len(values)


def range_of(values):
    return max(values) - min(values)


def total(values):
    return sum(values)
